out += "assets/images/hero.jpg\" as=\"image\">\n<link rel=\"dns-prefetch\" href=\"//fonts.googleapis.com\">\n<link rel=\"dns-prefetch\" href=\"//cdn.jsdelivr.net\">\n\n<!-- CSS Global -->\n<style>\n\n/* ============================================================\n   IBOUKOUN COSMETICS — Design System Global\n   Inspiré de Sculpted by Aimee : blanc dominant, épuré, aéré\n============================================================ */\n*,*::before,*::after{margin:0;padding:0;box-sizing:border-box;}\n:root{\n  --green:#2D9E35;--green-dark:#1B5E20;--green-light:#E8F5E9;--green-mid:#4DC657;\n  --navy:#0D1A5E;--navy-dark:#06103A;--navy-light:#E8EAF6;--navy-mid:#1a2d8a;\n  --gold:#C9920A;--gold-dark:#8B6200;--gold-light:#FFF8E1;--gold-mid:#E8B84B;\n  --cream:#FAF7F2;--cream-dark:#F2EDE4;--cream-mid:#F6F2EA;\n  --white:#FFFFFF;\n  --text:#0D1117;--text2:#4A4F6A;--text3:#9299B0;\n  --radius-xs:4px;--radius-sm:8px;--radius:14px;--radius-lg:20px;\n  --radius-xl:28px;--radius-pill:999px;\n  --shadow-xs:0 1px 4px rgba(13,26,94,.05);\n  --shadow-sm:0 2px 12px rgba(13,26,94,.07);\n  --shadow:0 6px 28px rgba(13,26,94,.09);\n  --shadow-lg:0 16px 56px rgba(13,26,94,.13);\n  --shadow-green:0 4px 20px rgba(45,158,53,.32);\n  --nav-h:68px;--ticker-h:36px;--container:1240px;--section-py:96px;\n}\nhtml{scroll-behavior:smooth;font-size:16px;}\nbody{\n  font-family:'DM Sans',sans-serif;\n  background:var(--white);color:var(--text);\n  overflow-x:hidden;-webkit-font-smoothing:antialiased;\n}\nimg{max-width:100%;height:auto;display:block;}\na{text-decoration:none;color:inherit;transition:color .2s;}\nul,ol{list-style:none;}\nbutton{cursor:pointer;font-family:'DM Sans',sans-serif;border:none;outline:none;background:none;}\ninput,textarea,select{font-family:'DM Sans',sans-serif;outline:none;}\n\n/* ============================================================\n   SKELETON LOADER\n============================================================ */\n#skeletonLoader{\n  position:fixed;inset:0;z-index:99999;\n  background:var(--white);\n  display:flex;flex-direction:column;\n  transition:opacity .35s ease,visibility .35s ease;\n  overflow:hidden;\n}\n#skeletonLoader.hidden{opacity:0;visibility:hidden;pointer-events:none;}\n@keyframes skShimmer{\n  0%{background-position:-600px 0;}\n  100%{background-position:600px 0;}\n}\n.sk-box{\n  background:linear-gradient(90deg,#f5f5f5 25%,#eaeaea 50%,#f5f5f5 75%);\n  background-size:600px 100%;\n  animation:skShimmer 1.4s ease-in-out infinite;\n  border-radius:6px;flex-shrink:0;\n}\n.sk-nav{\n  height:var(--nav-h);background:#fff;\n  border-bottom:1px solid rgba(0,0,0,.05);\n  display:flex;align-items:center;padding:0 5%;flex-shrink:0;\n}\n.sk-nav-inner{max-width:var(--container);margin:0 auto;width:100%;display:flex;align-items:center;gap:24px;}\n.sk-logo{display:flex;align-items:center;gap:10px;flex-shrink:0;}\n.sk-logo-img{width:36px;height:36px;border-radius:8px;}\n.sk-logo-text{display:flex;flex-direction:column;gap:4px;}\n.sk-nav-links{display:flex;align-items:center;gap:20px;flex:1;justify-content:center;}\n.sk-btn-nav{width:110px;height:36px;border-radius:999px;flex-shrink:0;}\n.sk-line{border-radius:4px;}\n.sk-body{flex:1;overflow:hidden;}\n.sk-hero{\n  height:calc(100vh - var(--nav-h));\n  background:linear-gradient(135deg,#0D1A5E 0%,#1a2d8a 100%);\n  display:flex;align-items:flex-end;\n  padding:0 clamp(16px,5%,64px) 64px;\n  position:relative;overflow:hidden;\n}\n.sk-hero::after{\n  content:'';position:absolute;inset:0;\n  background:linear-gradient(90deg,rgba(255,255,255,.03) 25%,rgba(255,255,255,.07) 50%,rgba(255,255,255,.03) 75%);\n  background-size:600px 100%;animation:skShimmer 1.8s ease-in-out infinite;\n}\n.sk-hero-content{display:flex;flex-direction:column;gap:16px;max-width:520px;position:relative;z-index:1;}\n.sk-hero-badge{width:200px;height:30px;border-radius:999px;background:rgba(255,255,255,.12);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-hero-h1-1{width:320px;height:52px;border-radius:8px;background:rgba(255,255,255,.12);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-hero-h1-2{width:240px;height:52px;border-radius:8px;background:rgba(255,255,255,.1);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;animation-delay:.1s;}\n.sk-hero-sub{width:400px;height:14px;border-radius:4px;background:rgba(255,255,255,.08);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-hero-sub2{width:320px;height:14px;border-radius:4px;background:rgba(255,255,255,.06);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;animation-delay:.1s;}\n.sk-hero-btns{display:flex;gap:12px;margin-top:8px;}\n.sk-hero-btn1{width:160px;height:48px;border-radius:999px;background:rgba(45,158,53,.4);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-hero-btn2{width:140px;height:48px;border-radius:999px;background:rgba(255,255,255,.1);animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;animation-delay:.1s;}\n.sk-page-hero{\n  background:var(--cream);\n  padding:72px clamp(16px,5%,64px) 64px;\n  display:flex;flex-direction:column;align-items:center;gap:16px;\n}\n.sk-page-hero-badge{width:120px;height:10px;border-radius:4px;animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-page-hero-title{width:340px;height:52px;border-radius:8px;animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-page-hero-sub{width:280px;height:14px;border-radius:4px;animation:skShimmer 1.4s ease-in-out infinite;background-size:600px 100%;}\n.sk-section{padding:80px clamp(16px,5%,64px);}\n.sk-section-header{display:flex;flex-direction:column;align-items:center;gap:12px;margin-bottom:48px;}\n.sk-section-eyebrow{width:100px;height:10px;border-radius:4px;}\n.sk-section-title{width:360px;height:40px;border-radius:8px;}\n.sk-section-sub{width:280px;height:13px;border-radius:4px;}\n.sk-products{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:24px;}\n.sk-product-card{border-radius:16px;overflow:hidden;border:1px solid rgba(0,0,0,.05);}\n.sk-product-img{height:260px;border-radius:0;}\n.sk-product-body{padding:20px;}\n.sk-product-cat{width:80px;height:10px;border-radius:4px;margin-bottom:10px;}\n.sk-product-name{width:140px;height:22px;border-radius:6px;margin-bottom:8px;}\n.sk-product-desc1{width:100%;height:11px;border-radius:4px;margin-bottom:6px;}\n.sk-product-desc2{width:75%;height:11px;border-radius:4px;margin-bottom:16px;}\n.sk-product-footer{display:flex;justify-content:space-between;align-items:center;}\n.sk-product-price{width:70px;height:24px;border-radius:6px;}\n.sk-product-btn{width:100px;height:36px;border-radius:999px;}\n.sk-temos{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:20px;}\n.sk-temo-card{border-radius:16px;padding:24px;border:1px solid rgba(0,0,0,.05);}\n.sk-temo-stars{display:flex;gap:4px;margin-bottom:12px;}\n.sk-temo-star{width:14px;height:14px;border-radius:3px;}\n.sk-temo-text1{width:100%;height:12px;border-radius:4px;margin-bottom:7px;}\n.sk-temo-text2{width:85%;height:12px;border-radius:4px;margin-bottom:7px;}\n.sk-temo-text3{width:65%;height:12px;border-radius:4px;margin-bottom:18px;}\n.sk-temo-author{display:flex;align-items:center;gap:10px;}\n.sk-temo-avatar{width:40px;height:40px;border-radius:50%;flex-shrink:0;}\n.sk-temo-info{flex:1;}\n.sk-temo-name{width:100px;height:13px;border-radius:4px;margin-bottom:6px;}\n.sk-temo-city{width:70px;height:10px;border-radius:4px;}\n@media(max-width:768px){\n  .sk-nav-links,.sk-btn-nav{display:none;}\n  .sk-hero-content{max-width:100%;}\n  .sk-hero-h1-1,.sk-hero-h1-2{width:100%;max-width:280px;}\n  .sk-hero-btns{flex-direction:column;}\n  .sk-hero-btn1,.sk-hero-btn2{width:100%;}\n  .sk-products{grid-template-columns:1fr 1fr;}\n  .sk-temos{grid-template-columns:1fr;}\n  .sk-section-title{width:240px;}\n}\n@media(max-width:480px){\n  .sk-products{grid-template-columns:1fr;}\n  .sk-section{padding:52px 16px;}\n}\n\n/* ============================================================\n   CONTAINER & SECTION\n============================================================ */\n.container{max-width:var(--container);margin:0 auto;padding:0 clamp(16px,5%,64px);width:100%;}\n.section{padding:var(--section-py) clamp(16px,5%,64px);}\n.section-white{background:var(--white);}\n.section-cream{background:var(--cream);}\n.section-navy{background:var(--navy);}\n\n/* ============================================================\n   SECTION HEADER — style épuré inspiré Sculpted\n   Plus de doubles lignes vertes — lettres espacées minimalistes\n============================================================ */\n.section-header{text-align:center;margin-bottom:64px;}\n.section-eyebrow{\n  display:inline-flex;align-items:center;gap:8px;\n  font-size:11px;font-weight:600;letter-spacing:2.5px;\n  text-transform:uppercase;color:var(--green);\n  margin-bottom:16px;\n}\n.section-eyebrow i{font-size:13px;}\n.section-h2{\n  font-family:'Cormorant Garamond',serif;\n  font-size:clamp(30px,3.2vw,48px);font-weight:700;\n  color:var(--navy);line-height:1.1;margin-bottom:14px;\n  letter-spacing:-.5px;\n}\n.section-sub{\n  font-size:15px;color:var(--text2);\n  max-width:520px;margin:0 auto;line-height:1.78;\n}\n\n/* ============================================================\n   BOUTONS\n============================================================ */\n.btn-primary{\n  display:inline-flex;align-items:center;gap:9px;\n  background:var(--green);color:#fff;\n  padding:14px 30px;border-radius:var(--radius-pill);\n  font-size:14px;font-weight:600;letter-spacing:.2px;\n  transition:all .25s;border:none;cursor:pointer;\n  box-shadow:var(--shadow-green);\n}\n.btn-primary:hover{background:var(--green-dark);transform:translateY(-2px);box-shadow:0 8px 28px rgba(45,158,53,.4);}\n.btn-primary i{font-size:17px;}\n.btn-navy{\n  display:inline-flex;align-items:center;gap:9px;\n  background:var(--navy);color:#fff;\n  padding:13px 28px;border-radius:var(--radius-pill);\n  font-size:14px;font-weight:600;transition:all .2s;border:none;cursor:pointer;\n}\n.btn-navy:hover{background:var(--navy-mid);transform:translateY(-1px);}\n.btn-outline-white{\n  display:inline-flex;align-items:center;gap:9px;\n  background:transparent;color:#fff;\n  padding:13px 28px;border-radius:var(--radius-pill);\n  font-size:14px;font-weight:500;\n  border:1.5px solid rgba(255,255,255,.4);transition:all .25s;\n}\n.btn-outline-white:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.8);}\n.btn-outline-green{\n  display:inline-flex;align-items:center;gap:9px;\n  background:transparent;color:var(--green);\n  padding:13px 28px;border-radius:var(--radius-pill);\n  font-size:14px;font-weight:600;\n  border:1.5px solid var(--green);transition:all .25s;\n}\n.btn-outline-green:hover{background:var(--green);color:#fff;}\n.btn-outline-navy{\n  display:inline-flex;align-items:center;gap:9px;\n  background:transparent;color:var(--navy);\n  padding:12px 26px;border-radius:var(--radius-pill);\n  font-size:14px;font-weight:600;\n  border:1.5px solid rgba(13,26,94,.2);transition:all .25s;\n}\n.btn-outline-navy:hover{background:var(--navy);color:#fff;border-color:var(--navy);}\n\n/* ============================================================\n   BADGES\n============================================================ */\n.badge-promo{\n  display:inline-flex;align-items:center;gap:4px;\n  background:linear-gradient(135deg,var(--gold),#E8A800);\n  color:#fff;padding:5px 13px;border-radius:var(--radius-pill);\n  font-size:11px;font-weight:700;letter-spacing:.3px;\n  box-shadow:0 2px 8px rgba(201,146,10,.25);\n}\n.badge-new{\n  display:inline-flex;align-items:center;gap:4px;\n  background:var(--green);color:#fff;\n  padding:5px 11px;border-radius:var(--radius-pill);\n  font-size:11px;font-weight:700;\n}\n\n/* ============================================================\n   FLASH\n============================================================ */\n.flash-msg{display:flex;align-items:center;gap:10px;padding:14px 20px;border-radius:var(--radius);font-size:14px;font-weight:500;margin-bottom:20px;}\n.flash-msg i{font-size:18px;flex-shrink:0;}\n.flash-success{background:#E8F5E9;color:#1B5E20;border:1px solid #A5D6A7;}\n.flash-error{background:#FFEBEE;color:#C62828;border:1px solid #EF9A9A;}\n\n/* ============================================================\n   PAGINATION\n============================================================ */\n.pagination{display:flex;gap:6px;justify-content:center;margin-top:40px;flex-wrap:wrap;}\n.pag-btn{padding:8px 16px;border-radius:var(--radius-sm);border:1.5px solid rgba(0,0,0,.1);background:#fff;font-size:13px;font-weight:500;color:var(--text2);transition:.2s;text-decoration:none;}\n.pag-btn:hover,.pag-btn.active{background:var(--navy);color:#fff;border-color:var(--navy);}\n\n/* ============================================================\n   BOUTON WHATSAPP FLOTTANT\n============================================================ */\n.wa-float{position:fixed;bottom:32px;right:24px;z-index:9000;display:flex;align-items:center;}\n.wa-float-label{background:var(--navy);color:#fff;padding:10px 18px;border-radius:var(--radius-pill) 0 0 var(--radius-pill);font-size:12px;font-weight:600;box-shadow:var(--shadow);opacity:0;transform:translateX(12px);transition:opacity .3s,transform .3s;pointer-events:none;white-space:nowrap;}\n.wa-float:hover .wa-float-label{opacity:1;transform:translateX(0);}\n.wa-float-btn{width:56px;height:56px;border-radius:50%;background:linear-gradient(135deg,#25D366,#1EB85A);display:flex;align-items:center;justify-content:center;box-shadow:0 4px 24px rgba(37,211,102,.4);transition:transform .25s;position:relative;}\n.wa-float-btn:hover{transform:scale(1.1);}\n.wa-float-btn i{font-size:26px;color:#fff;}\n.wa-pulse{position:absolute;top:-3px;right:-3px;width:15px;height:15px;border-radius:50%;background:#FF3B30;border:2.5px solid var(--white);animation:pulseBadge 2s infinite;}\n\n/* ============================================================\n   ANIMATIONS\n============================================================ */\n@keyframes pulseBadge{0%,100%{transform:scale(1)}50%{transform:scale(1.35)}}\n@keyframes fadeInUp{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:translateY(0)}}\n@keyframes floatY{0%,100%{transform:translateY(0)}50%{transform:translateY(-14px)}}\n@keyframes spin{to{transform:rotate(360deg)}}\n@keyframes slideDown{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:translateY(0)}}\n@keyframes menuItemIn{from{opacity:0;transform:translateX(-18px)}to{opacity:1;transform:translateX(0)}}\n@keyframes tickerScroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n\n.reveal{opacity:0;transform:translateY(24px);transition:opacity .6s ease,transform .6s ease;}\n.reveal.visible{opacity:1;transform:translateY(0);}\n.reveal-delay-1{transition-delay:.1s;}\n.reveal-delay-2{transition-delay:.2s;}\n.reveal-delay-3{transition-delay:.3s;}\n\n/* ============================================================\n   TICKER DÉFILANT — inspiré Sculpted by Aimee\n   Bande fine au-dessus de la nav avec USP en scrolling continu\n============================================================ */\n.site-ticker{\n  background:var(--navy-dark);\n  height:var(--ticker-h);\n  overflow:hidden;\n  position:relative;\n  z-index:1001;\n}\n.ticker-track{\n  display:flex;align-items:center;\n  height:100%;\n  animation:tickerScroll 28s linear infinite;\n  width:max-content;\n}\n.ticker-track:hover{animation-play-state:paused;}\n.ticker-item{\n  display:inline-flex;align-items:center;gap:8px;\n  padding:0 36px;\n  font-size:11px;font-weight:600;color:rgba(255,255,255,.85);\n  letter-spacing:.8px;text-transform:uppercase;\n  white-space:nowrap;\n}\n.ticker-item i{font-size:13px;color:var(--green-mid);flex-shrink:0;}\n.ticker-sep{\n  width:4px;height:4px;border-radius:50%;\n  background:rgba(255,255,255,.2);flex-shrink:0;\n}\n\n/* ============================================================\n   NAVIGATION DESKTOP — blanc épuré, minimaliste\n============================================================ */\nnav.main-nav{\n  position:sticky;top:0;z-index:1000;\n  background:#fff;\n  border-bottom:1px solid rgba(0,0,0,.08);\n  padding:0 5%;height:var(--nav-h);\n  transition:box-shadow .3s;\n}\nnav.main-nav.scrolled{\n  box-shadow:0 2px 24px rgba(0,0,0,.07);\n}\n.nav-inner{\n  max-width:var(--container);margin:0 auto;height:100%;\n  display:flex;align-items:center;justify-content:space-between;gap:16px;\n}\n\n/* Logo */\n.nav-logo{display:flex;align-items:center;gap:10px;flex-shrink:0;}\n.nav-logo-img{height:38px;width:auto;display:flex;align-items:center;}\n.nav-logo-img img{height:38px;width:auto;object-fit:contain;border-radius:6px;}\n.nav-logo-text{display:flex;flex-direction:column;line-height:1.15;}\n.nav-logo-text .brand-name{\n  font-family:'Cormorant Garamond',serif;\n  font-size:17px;font-weight:700;color:var(--navy);letter-spacing:-.3px;\n}\n.nav-logo-text .brand-tag{\n  font-size:9px;color:var(--text3);\n  letter-spacing:2px;text-transform:uppercase;margin-top:1px;\n}\n\n/* Liens nav — style minimaliste */\n.nav-links{\n  display:flex;align-items:center;gap:0;\n  flex:1;justify-content:center;\n}\n.nav-links a{\n  font-size:13px;font-weight:500;color:var(--text2);\n  padding:8px 12px;\n  transition:color .2s;white-space:nowrap;\n  position:relative;\n  display:inline-flex;align-items:center;gap:5px;\n  letter-spacing:.1px;\n}\n.nav-links a:hover{color:var(--navy);}\n.nav-links a.active{color:var(--navy);font-weight:600;}\n/* Soulignement fin au hover et active — style Sculpted */\n.nav-links a::after{\n  content:'';position:absolute;\n  bottom:0;left:12px;right:12px;\n  height:1.5px;background:var(--navy);\n  transform:scaleX(0);transition:transform .25s ease;\n  border-radius:2px;\n}\n.nav-links a:hover::after,\n.nav-links a.active::after{transform:scaleX(1);}\n/* Promo — même style, icône verte */\n.nav-links a.nav-promo i{font-size:13px;color:var(--green);}\n.promo-dot{\n  width:5px;height:5px;border-radius:50%;\n  background:var(--green);display:inline-block;\n  animation:pulseBadge 2s infinite;flex-shrink:0;\n}\n\n/* Actions nav */\n.nav-actions{display:flex;align-items:center;gap:8px;flex-shrink:0;}\n.nav-wa-btn{\n  display:flex;align-items:center;gap:7px;\n  background:var(--green);color:#fff;\n  padding:10px 22px;border-radius:var(--radius-pill);\n  font-size:13px;font-weight:600;\n  transition:all .2s;white-space:nowrap;\n  box-shadow:0 2px 12px rgba(45,158,53,.28);\n}\n.nav-wa-btn:hover{background:var(--green-dark);transform:translateY(-1px);}\n.nav-wa-btn i{font-size:16px;}\n\n/* Hamburger */\n.hamburger{\n  display:none;width:40px;height:40px;\n  border-radius:var(--radius-sm);\n  background:transparent;border:none;\n  flex-direction:column;align-items:center;\n  justify-content:center;gap:5px;\n  cursor:pointer;padding:0;transition:background .2s;\n  flex-shrink:0;\n}\n.hamburger:hover{background:rgba(13,26,94,.05);}\n.hamburger span{\n  display:block;width:22px;height:1.5px;\n  background:var(--navy);border-radius:2px;\n  transition:transform .32s cubic-bezier(.23,1,.32,1),opacity .2s,width .2s;\n}\n.hamburger.open span:nth-child(1){transform:translateY(6.5px) rotate(45deg);}\n.hamburger.open span:nth-child(2){opacity:0;width:0;}\n.hamburger.open span:nth-child(3){transform:translateY(-6.5px) rotate(-45deg);}\n\n/* ============================================================\n   MENU MOBILE — conservé tel quel (il marche bien)\n============================================================ */\n.nav-mobile-menu{\n  display:none;position:fixed;\n  top:0;left:0;right:0;bottom:0;z-index:998;\n  flex-direction:column;background:var(--navy-dark);overflow:hidden;\n}\n.nav-mobile-menu.open{display:flex;}\n.mobile-menu-header{\n  display:flex;align-items:center;justify-content:space-between;\n  padding:0 20px;height:var(--nav-h);\n  border-bottom:1px solid rgba(255,255,255,.08);flex-shrink:0;\n}\n.mobile-menu-logo{display:flex;align-items:center;gap:8px;}\n.mobile-menu-logo img{height:34px;width:auto;object-fit:contain;border-radius:6px;}\n.mobile-menu-logo-text{display:flex;flex-direction:column;line-height:1.1;}\n.mobile-menu-logo-text .m-brand{font-family:'Cormorant Garamond',serif;font-size:15px;font-weight:700;color:#fff;}\n.mobile-menu-logo-text .m-tag{font-size:8px;color:rgba(255,255,255,.4);letter-spacing:1.5px;text-transform:uppercase;}\n.mobile-menu-close{\n  width:38px;height:38px;border-radius:50%;\n  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);\n  display:flex;align-items:center;justify-content:center;\n  cursor:pointer;transition:background .2s;flex-shrink:0;pointer-events:auto;\n}\n.mobile-menu-close:hover{background:rgba(255,255,255,.16);}\n.mobile-menu-close *{pointer-events:none;}\n.mobile-menu-body{flex:1;padding:16px 0;overflow-y:auto;}\n.mobile-nav-item{\n  display:flex;align-items:center;justify-content:space-between;\n  padding:15px 24px;font-size:16px;font-weight:500;\n  color:rgba(255,255,255,.75);text-decoration:none;\n  border-left:3px solid transparent;transition:all .2s;\n}\n.mobile-nav-item:hover{color:#fff;background:rgba(255,255,255,.05);border-left-color:var(--green);}\n.mobile-nav-item.active{color:#fff;font-weight:600;background:rgba(45,158,53,.12);border-left-color:var(--green);}\n.mobile-nav-item-left{display:flex;align-items:center;gap:14px;}\n.mobile-nav-icon{width:38px;height:38px;border-radius:10px;background:rgba(255,255,255,.07);display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:background .2s;}\n.mobile-nav-item:hover .mobile-nav-icon,.mobile-nav-item.active .mobile-nav-icon{background:rgba(45,158,53,.2);}\n.mobile-nav-icon i{font-size:17px;color:rgba(255,255,255,.6);}\n.mobile-nav-item:hover .mobile-nav-icon i,.mobile-nav-item.active .mobile-nav-icon i{color:var(--green-mid);}\n.mobile-nav-label{display:flex;flex-direction:column;gap:2px;}\n.mobile-nav-label span{display:block;}\n.mobile-nav-label .nav-label-main{font-size:15px;color:inherit;}\n.mobile-nav-label .nav-label-sub{font-size:11px;color:rgba(255,255,255,.35);font-weight:400;}\n.mobile-nav-arrow{font-size:16px;color:rgba(255,255,255,.25);}\n.mobile-nav-item:hover .mobile-nav-arrow,.mobile-nav-item.active .mobile-nav-arrow{color:rgba(255,255,255,.5);}\n.mobile-promo-badge{display:inline-flex;align-items:center;gap:4px;background:rgba(201,146,10,.25);border:1px solid rgba(201,146,10,.4);color:var(--gold-mid);padding:2px 9px;border-radius:var(--radius-pill);font-size:10px;font-weight:700;letter-spacing:.3px;text-transform:uppercase;}\n.mobile-menu-sep{height:1px;background:rgba(255,255,255,.06);margin:8px 24px;}\n.mobile-menu-footer{padding:20px 20px max(20px,env(safe-area-inset-bottom));border-top:1px solid rgba(255,255,255,.07);flex-shrink:0;}\n.mobile-wa-btn{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;padding:16px;background:linear-gradient(135deg,#25D366,#1EB85A);color:#fff;border-radius:var(--radius-pill);font-size:15px;font-weight:700;text-decoration:none;box-shadow:0 4px 20px rgba(37,211,102,.35);transition:transform .2s,box-shadow .2s;}\n.mobile-wa-btn:hover{transform:translateY(-1px);box-shadow:0 6px 24px rgba(37,211,102,.45);}\n.mobile-wa-btn i{font-size:20px;}\n.mobile-menu-social{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:16px;}\n.mobile-social-link{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;transition:background .2s;text-decoration:none;}\n.mobile-social-link:hover{background:rgba(255,255,255,.14);}\n.mobile-social-link i{font-size:17px;color:rgba(255,255,255,.65);}\n.nav-mobile-menu.open .mobile-nav-item{animation:menuItemIn .3s ease both;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(1){animation-delay:.05s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(2){animation-delay:.08s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(3){animation-delay:.11s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(4){animation-delay:.14s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(5){animation-delay:.17s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(6){animation-delay:.20s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(7){animation-delay:.23s;}\n.nav-mobile-menu.open .mobile-nav-item:nth-child(8){animation-delay:.26s;}\n\n/* ============================================================\n   PAGE HERO INTÉRIEURE — inspiré Sculpted\n   Fond crème/blanc au lieu de navy systématique\n   Titre en navy foncé, aéré, propre\n============================================================ */\n.page-hero{\n  background:var(--cream);\n  padding:80px 5% 72px;\n  text-align:center;\n  position:relative;overflow:hidden;\n  border-bottom:1px solid rgba(0,0,0,.06);\n}\n/* Accent décoratif très subtil */\n.page-hero::before{\n  content:'';position:absolute;\n  top:0;left:0;right:0;height:3px;\n  background:linear-gradient(90deg,var(--green),var(--navy),var(--gold));\n  opacity:.25;\n}\n.page-hero-content{position:relative;z-index:1;max-width:640px;margin:0 auto;}\n.page-hero-eyebrow{\n  display:inline-block;\n  font-size:11px;font-weight:600;letter-spacing:2.5px;\n  text-transform:uppercase;color:var(--green);\n  margin-bottom:18px;\n}\n.page-hero-title{\n  font-family:'Cormorant Garamond',serif;\n  font-size:clamp(36px,4.5vw,60px);font-weight:700;\n  color:var(--navy);line-height:1.06;\n  margin-bottom:16px;letter-spacing:-1px;\n}\n.page-hero-sub{\n  font-size:16px;color:var(--text2);\n  max-width:480px;margin:0 auto;line-height:1.78;\n}\n\n/* ============================================================\n   FAQ\n============================================================ */\n.faq-item{border:1px solid rgba(0,0,0,.07);border-radius:var(--radius);overflow:hidden;margin-bottom:10px;}\n.faq-question{width:100%;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 22px;background:#fff;border:none;cursor:pointer;text-align:left;font-size:15px;font-weight:600;color:var(--navy);font-family:'DM Sans',sans-serif;transition:background .2s;}\n.faq-question:hover{background:var(--cream);}\n.faq-question i{font-size:22px;color:var(--text3);transition:transform .3s;flex-shrink:0;}\n.faq-answer{max-height:0;overflow:hidden;transition:max-height .35s ease;font-size:15px;color:var(--text2);line-height:1.75;}\n.faq-answer-inner{padding:4px 22px 20px;}\n.faq-item.open .faq-question{background:var(--cream);}\n.faq-item.open .faq-question i{transform:rotate(45deg);color:var(--green);}\n.faq-item.open .faq-answer{max-height:300px;}\n\n/* ============================================================\n   EMPTY STATE\n============================================================ */\n.empty-state{text-align:center;padding:80px 20px;color:var(--text3);font-size:15px;}\n.empty-state i{font-size:54px;display:block;margin-bottom:16px;opacity:.2;}\n\n/* ============================================================\n   RESPONSIVE GLOBAL\n============================================================ */\n@media(max-width:1100px){\n  .nav-links a{font-size:12px;padding:8px 9px;}\n}\n@media(max-width:1024px){\n  :root{--section-py:80px;}\n  .nav-wa-btn{padding:9px 16px;font-size:12px;}\n}\n@media(max-width:768px){\n  :root{--section-py:64px;--nav-h:64px;--ticker-h:32px;}\n  .nav-links,.nav-wa-btn{display:none;}\n  .hamburger{display:flex;}\n  .wa-float{bottom:24px;right:20px;}\n  .wa-float-btn{width:52px;height:52px;}\n  .wa-float-btn i{font-size:24px;}\n  .wa-float-label{display:none;}\n  .section{padding:var(--section-py) clamp(16px,4%,40px);}\n  .container{padding:0 clamp(16px,4%,40px);}\n  .section-header{margin-bottom:44px;}\n  .section-h2{font-size:clamp(26px,7vw,36px);}\n  .page-hero{padding:60px 4% 52px;}\n  .page-hero-title{font-size:clamp(28px,8vw,44px);}\n  .page-hero-sub{font-size:15px;}\n  .ticker-item{font-size:10px;padding:0 24px;}\n}\n@media(max-width:480px){\n  :root{--section-py:52px;}\n  .nav-logo-text .brand-name{font-size:14px;}\n  .nav-logo-text .brand-tag{font-size:8px;letter-spacing:1.2px;}\n  .nav-logo-img img{height:30px;}\n  nav.main-nav{padding:0 4%;}\n  .section{padding:var(--section-py) 16px;}\n  .container{padding:0 16px;}\n  .section-h2{font-size:clamp(24px,8vw,32px);}\n  .page-hero{padding:52px 4% 44px;}\n  .page-hero-title{font-size:clamp(26px,9vw,36px);}\n  .ticker-item span:not(.ticker-sep){display:none;}\n  .ticker-item i{display:none;}\n}\n@media(max-width:360px){\n  .section-h2{font-size:24px;}\n  .page-hero-title{font-size:26px;}\n  .mobile-nav-item{padding:12px 16px;}\n  .mobile-nav-label .nav-label-sub{display:none;}\n}\n</style>\n</head>\n<body>\n\n<!-- SKELETON LOADER -->\n<div id=\"skeletonLoader\">\n  <div class=\"sk-nav\">\n    <div class=\"sk-nav-inner\">\n      <div class=\"sk-logo\">\n        <div class=\"sk-box sk-logo-img\"></div>\n        <div class=\"sk-logo-text\">\n          <div class=\"sk-box sk-line\" style=\"width:140px;height:14px;\"></div>\n          <div class=\"sk-box sk-line\" style=\"width:80px;height:9px;margin-top:4px;\"></div>\n        </div>\n      </div>\n      <div class=\"sk-nav-links\">\n        <div class=\"sk-box sk-line\" style=\"width:56px;height:12px;\"></div>\n        <div class=\"sk-box sk-line\" style=\"width:56px;height:12px;\"></div>\n        <div class=\"sk-box sk-line\" style=\"width:80px;height:12px;\"></div>\n        <div class=\"sk-box sk-line\" style=\"width:72px;height:12px;\"></div>\n        <div class=\"sk-box sk-line\" style=\"width:56px;height:12px;\"></div>\n      </div>\n      <div class=\"sk-box sk-btn-nav\"></div>\n    </div>\n  </div>\n  <div class=\"sk-body\" id=\"skBody\"></div>\n</div>\n\n<!-- TICKER DÉFILANT -->\n<div class=\"site-ticker\" id=\"siteTicker\">\n  <div class=\"ticker-track\">\n    <!-- Première copie -->\n    <span class=\"ticker-item\"><i class=\"ri-leaf-line\"></i>Soins 100% naturels</span>\n    <span class=\"ticker-item ticker-sep\"></span>\n    <span class=\"ticker-item\"><i class=\"ri-map-pin-line\"></i>Fabriqués à Parakou, Bénin</span>\n    <span class=\"ticker-item ticker-sep\"></span>\n    <span class=\"ticker-item\"><i class=\"ri-truck-line\"></i>Livraison partout au Bénin</span>\n    <span class=\"ticker-item ticker-sep\"></span>\n    <span class=\"ticker-item\"><i class=\"ri-group-line\"></i>+500 clients satisfaits</span>\n    <span class=\"ticker-item ticker-sep\"></span>\n    <span class=\"ticker-item\"><i class=\"ri-award-line\"></i>5 ans d'expertise naturelle</span>\n    <span class=\"ticker-item ticker-sep\"></span>\n    <span class=\"ticker-item\"><i class=\"ri-whatsapp-line\"></i>Commandez sur WhatsApp</span>\n    <span class=\"ticker-item ticker-sep\"></span>\n    ";
